const bank=globalThis.PAPER_BANK;
const bankQuestions=new Map(bank.questions.map(q=>[q.id,q]));
const bankPapers=new Map(bank.papers.map(p=>[p.id,p]));
const bankDocs=new Map(bank.documents.map(d=>[d.id,d]));
const kindLabel=k=>k==='sample'?'Sample booklet':'ISI archive';
const checkedQuestion=q=>q.status==='verified'&&Number.isInteger(q.correctIndex);
const activeQuestions=()=>test?.paperId?bankPapers.get(test.paperId).questionIds.map(id=>bankQuestions.get(id)):questions[test.track].map((q,i)=>({...q,id:`${test.track}-${i}`,stem:q.q,correctIndex:q.answer,status:'verified',number:String(i+1)}));
const questionNumber=q=>q.sourceNumber||q.number;
function questionBody(q){return `${q.context?`<p>${rich(q.context)}</p>`:''}${q.images?.length?q.images.map((src,i)=>`<a class="question-image-link" href="${safe(src)}" target="_blank" rel="noopener noreferrer" title="Enlarge original question"><img class="question-image" src="${safe(src)}" alt="Original question ${safe(questionNumber(q))}, excerpt ${i+1}. Open to enlarge." loading="lazy"></a>`).join(''):rich(q.stem)}${q.paper==='PEB'&&q.options&&!q.imageOptions?`<ol type="A" class="review-options">${q.options.map(o=>`<li>${rich(o)}</li>`).join('')}</ol>`:''}`;}
const rich=s=>safe(s??'').replace(/\n/g,'<br>');
function mathNow(){if(globalThis.renderMathInElement)renderMathInElement($('#content'),{delimiters:[{left:'$$',right:'$$',display:true},{left:'$',right:'$',display:false},{left:'\\(',right:'\\)',display:false},{left:'\\[',right:'\\]',display:true}],throwOnError:false,trust:false,strict:'ignore'});}
function questionSource(q){const d=bankDocs.get(q.sourceDoc);return d?`<a class="source-link" href="${d.url}#page=${q.sourcePage}" target="_blank" rel="noopener noreferrer">Original · PDF page ${q.sourcePage} ↗</a>`:'';}
function questionCaveat(q){return q.status==='needs_review'?'<div class="review-notice">Source issue / conditional answer · Excluded from automatic scoring</div>':'';}
function worked(q){return `${questionCaveat(q)}<div class="solution"><b>Answer</b><div>${rich(q.answer)}</div><hr><b>Worked solution</b><div>${rich(q.solution)}${(q.solutionImages||[]).map(src=>`<a href="${safe(src)}" target="_blank" rel="noopener noreferrer" class="question-image-link"><img class="question-image" src="${safe(src)}" loading="lazy" alt="Solution diagram for question ${safe(questionNumber(q))}; open to enlarge"></a>`).join('')}</div></div>${q.notes?`<p class="source-note">${rich(q.notes)}</p>`:''}${questionSource(q)}`;}
function trackCard(t){const ps=bank.papers.filter(p=>p.paper===t&&p.itemCount),count=ps.reduce((n,p)=>n+p.itemCount,0);return `<article class="track ${t.toLowerCase()}"><div class="track-top"><span class="track-symbol">${t==='PEA'?'∑':'ƒ'}</span><span class="pill">${t==='PEA'?'OBJECTIVE':'DESCRIPTIVE'}</span></div><h3>${t}<span>Paper ${t==='PEA'?'A':'B'}</span></h3><p>${t==='PEA'?'Year-wise questions & worked answers':'Questions, hints & worked solutions'}</p><div class="track-bottom"><span>${count} indexed items · ${ps.length} study sets</span><button class="text-button" data-track="${t}">Choose a paper ↗</button></div></article>`;}
function paperRow(year){const available=bank.papers.filter(p=>p.year===year&&p.itemCount),count=available.reduce((n,p)=>n+p.itemCount,0);return `<div class="paper-row"><span class="paper-file">▤</span><div class="paper-name">ISI MSQE ${year}<small>${count?`${count} indexed items`:'Original booklets available'}</small></div><button class="text-button" data-year="${year}">Explore ↗</button></div>`;}
function overview(){const sets=bank.papers.filter(p=>p.itemCount).length;return `<section class="hero main-hero"><div class="hero-copy"><div class="eyebrow">ECONPREP</div><h1>ISI MSQE<br><span>Preparation</span></h1><p>Original papers. Hints. Worked solutions.</p><div class="hero-actions"><button class="btn light" data-go="papers">Choose a paper ↗</button><button class="hero-link" data-go="syllabus">Syllabus →</button></div></div></section><div class="stats">${stat('▤',bank.years,'Years of source papers')}${stat('∑',bank.questions.length,'Indexed question items')}${stat('✓',bank.questions.filter(q=>q.status==='verified').length,'Checked solutions')}${stat('◷',history.length,'Sessions completed')}</div><div class="section-head"><h2>Choose your paper</h2><span class="pill">${sets} STUDY SETS</span></div><div class="tracks">${trackCard('PEA')}${trackCard('PEB')}</div><div class="notice">1998–2024 source sets are indexed. Independent solutions; source issues are flagged.</div><div class="section-head"><h2>Paper library</h2><button class="text-button" data-go="papers">All years ↗</button></div><div class="paper-table">${[2024,2023,2022,2016,2013].map(paperRow).join('')}</div>`;}
function papers(){return `${heading('Past year papers','1998–2024 · Exam archives and sample booklets')}<div class="filters"><input id="search" type="search" aria-label="Search paper year" placeholder="Search year"><select id="paper-track" aria-label="Paper track"><option value="PEA">PEA · Objective</option><option value="PEB">PEB · Descriptive</option></select><select id="sort" aria-label="Sort years"><option value="new">Newest first</option><option value="old">Oldest first</option></select></div><div class="coverage-key"><span>✓ Study set available</span><span>▤ Source only: answers pending</span><span>! Source issue: not auto-scored</span></div><div class="library-grid" id="paper-list"></div>`;}
function renderPapers(){const t=$('#paper-track').value;let ps=bank.papers.filter(p=>p.paper===t&&String(p.year).includes($('#search').value.trim()));if($('#sort').value==='new')ps=ps.slice().reverse();$('#paper-list').innerHTML=ps.map(p=>`<article class="library-card"><div class="paper-card-top"><span class="pill">${t} · ${kindLabel(p.kind)}</span><span class="coverage-status ${p.itemCount?'ready':''}">${p.itemCount?'✓ Study set':'▤ Source only'}</span></div><h3>ISI MSQE ${p.year}${p.variant==='sample'?' · Sample':p.variant==='official'?' · Written archive':''}</h3><p>${p.itemCount?`${p.itemCount} indexed items · ${p.checkedCount} checked${p.reviewCount?`<br>${p.reviewCount} source issues flagged`:''}`:'Original booklet available<br>Structured solutions pending'}</p><button class="btn ${p.itemCount?'':'outline'}" data-bank-preview="${p.id}">${p.itemCount?'Open paper':'View sources'} ↗</button></article>`).join('')||'<div class="empty">No matching years.</div>';}
function practice(){const ready=bank.papers.filter(p=>p.paper===track&&p.itemCount).reverse();return `${heading('Practice','Choose an indexed paper to begin.')}<div class="tabs"><button data-switch="PEA" class="${track==='PEA'?'active':''}">PEA · Objective</button><button data-switch="PEB" class="${track==='PEB'?'active':''}">PEB · Descriptive</button></div><div class="notice">${track==='PEA'?'Practice scoring: +1 correct, 0 otherwise. Flagged source issues are not scored. This is not an official marking scheme.':'Practice on paper. Open the Hint or Solution tab when needed; no answer writing is required.'}</div><div class="library-grid">${ready.map(p=>`<article class="library-card"><span class="pill">${kindLabel(p.kind)}</span><h3>${p.year} · ${track}${p.variant==='sample'?' · Sample':p.variant==='official'?' · Written archive':''}</h3><p>${p.itemCount} indexed items · ${p.checkedCount} checked</p><button class="btn" data-bank-preview="${p.id}">Start practice ↗</button><button class="text-button" data-bank-review="${p.id}">Read solutions</button></article>`).join('')||'<div class="empty">No indexed papers for this track yet.</div>'}</div><div class="section-head" style="margin-top:28px"><h2>All source papers</h2><button class="text-button" data-go="papers">Browse ↗</button></div>`;}
function paperPreview(year,t=track,paperId){const p=bankPapers.get(paperId||`${year}-${t}`);if(!p)return;modal(`<span class="eyebrow">${kindLabel(p.kind)} · ${t}</span><h2>${year} · ${t}</h2>${p.itemCount?`<p>${p.itemCount} indexed items (${p.mainCount} main questions). ${p.checkedCount} checked solutions${p.reviewCount?`; ${p.reviewCount} source issues flagged`:''}.</p><p class="dialog-small">Independently derived solutions; not an official answer key.</p>${t==='PEA'?'<label class="timer-setting" for="practice-duration">Practice timer<select id="practice-duration"><option value="120">120 minutes</option><option value="60">60 minutes</option><option value="30">30 minutes</option></select></label>':''}<div class="dialog-actions"><button class="btn outline" data-bank-review="${p.id}">Read solutions</button><button class="btn" data-bank-start="${p.id}">Start practice ↗</button></div>`:'<p>The original source is available. Its questions and answers have not yet been transcribed and checked.</p>'}<details class="source-documents" ${p.itemCount?'':'open'}><summary>Original PDFs (${p.documents.length})</summary>${p.documents.map(id=>{const d=bankDocs.get(id);return `<a class="source-link" href="${d.url}" target="_blank" rel="noopener noreferrer">${safe(d.filename)} ↗</a>`;}).join('')}</details><button class="text-button" data-close>Close</button>`);}
function startPaper(id){const p=bankPapers.get(id);if(!p?.itemCount)return;const mins=Number($('#practice-duration')?.value)||120;closeModal();clearInterval(tick);track=p.paper;test={paperId:id,track,index:0,answers:{},reviewed:{},helpUsed:{},startedAt:Date.now(),tab:'question',end:Date.now()+mins*60000,done:false};$('#crumb').textContent=p.title;$$('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page==='practice'));renderTest();window.scrollTo(0,0);if(track==='PEA')tick=setInterval(()=>{if(!test||test.done)return;const left=Math.max(0,Math.ceil((test.end-Date.now())/1000));if($('#timer'))$('#timer').textContent=clockText(left);if(!left){closeModal();finish()}},1000);}
function start(t){const p=bank.papers.filter(p=>p.paper===t&&p.itemCount).at(-1);if(p)paperPreview(p.year,t);}
function clockText(n){return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;}
function answered(i){return test.track==='PEB'?Boolean(test.reviewed[i]):test.answers[i]!==undefined;}
function renderTest(){const qs=activeQuestions(),q=qs[test.index],i=test.index,p=bankPapers.get(test.paperId);$('#content').innerHTML=`${heading(p.title,kindLabel(p.kind))}<div class="test-heading"><span class="pill">${test.track==='PEA'?'OBJECTIVE':'SELF-PRACTICE'}</span>${test.track==='PEA'?`<span class="timer" id="timer">${clockText(Math.max(0,Math.ceil((test.end-Date.now())/1000)))}</span>`:''}</div><div class="test-layout"><article class="question-card"><div class="q-meta">Question ${safe(questionNumber(q))} · ${safe(q.topic)} · ${i+1}/${qs.length}</div>${questionCaveat(q)}${test.track==='PEA'?`<div class="question-stem">${questionBody(q)}</div>${q.options.map((o,j)=>`<label class="option ${test.answers[i]===j?'selected':''}"><input type="radio" name="answer" value="${j}" ${test.answers[i]===j?'checked':''}><span>${safe(q.sourceOptionLabels?.[j]||String.fromCharCode(65+j))}.</span><span>${q.imageOptions?'Select this option':rich(o)}</span></label>`).join('')}<button class="text-button" id="clear-answer">Clear answer</button>`:`<div class="tabs question-tabs" role="tablist" aria-label="Question help">${['question','hint','solution'].map(tab=>`<button role="tab" id="tab-${tab}" aria-controls="question-panel" aria-selected="${test.tab===tab}" data-question-tab="${tab}" class="${test.tab===tab?'active':''}">${tab[0].toUpperCase()+tab.slice(1)}</button>`).join('')}</div><div id="question-panel" role="tabpanel" aria-labelledby="tab-${test.tab}"><div class="question-stem">${questionBody(q)}</div>${test.tab==='hint'?`<div class="solution hint-panel"><b>Hint</b><div>${rich(q.hint)}</div></div>`:test.tab==='solution'?worked(q):''}</div><button class="btn outline mark-practiced" id="mark-practiced" aria-pressed="${answered(i)}">${answered(i)?'✓ Practiced':'Mark as practiced'}</button>`}<div class="question-source-row">${questionSource(q)}</div><div class="q-actions"><button class="btn outline" id="bookmark">${bookmarks.includes(q.id)?'✓ Saved':'♧ Save'}</button><div><button class="btn outline" id="prev" ${i?'':'disabled'}>← Back</button><button class="btn" id="next">${i===qs.length-1?'Finish':'Next →'}</button></div></div></article><section class="test-side"><h3>Questions</h3><div class="palette">${qs.map((x,j)=>`<button aria-label="Question ${safe(questionNumber(x))}" data-question="${j}" class="${answered(j)?'answered':''} ${i===j?'current':''} ${x.status==='needs_review'?'review-question':''}">${safe(questionNumber(x))}</button>`).join('')}</div><button class="btn" id="submit">${test.track==='PEA'?'Submit test':'Finish practice'}</button></section></div>`;
 if(test.track==='PEA'){$$('input[name="answer"]').forEach(el=>el.onchange=()=>{test.answers[i]=Number(el.value);renderTest()});$('#clear-answer').onclick=()=>{delete test.answers[i];renderTest()};}else{$('#mark-practiced').onclick=()=>{test.reviewed[i]=!test.reviewed[i];renderTest()};$$('[data-question-tab]').forEach(b=>b.onclick=()=>{test.tab=b.dataset.questionTab;if(test.tab!=='question'){test.helpUsed[i]??={};test.helpUsed[i][test.tab]=true;}renderTest();$(`#tab-${test.tab}`).focus();});}
 $('#prev').onclick=()=>{if(test.index){test.index--;test.tab='question';renderTest();}};$('#next').onclick=()=>{if(i<qs.length-1){test.index++;test.tab='question';renderTest();window.scrollTo(0,0);}else confirmSubmit();};$('#submit').onclick=confirmSubmit;$('#bookmark').onclick=()=>{toggleBankBookmark(q.id);renderTest();};$$('[data-question]').forEach(b=>b.onclick=()=>{test.index=Number(b.dataset.question);test.tab='question';renderTest();window.scrollTo(0,0);});mathNow();}
function toggleBankBookmark(id){bookmarks=bookmarks.includes(id)?bookmarks.filter(x=>x!==id):[...bookmarks,id];save('econprep-bookmarks',bookmarks);}
function confirmSubmit(){const qs=activeQuestions(),n=qs.filter((_,i)=>answered(i)).length;modal(`<h2>Finish ${test.track} practice?</h2><p>${n}/${qs.length} ${test.track==='PEA'?'answered':'marked as practiced'}.${test.track==='PEA'&&qs.some(q=>!checkedQuestion(q))?' Flagged source issues will not be scored.':''}</p><div class="dialog-actions"><button class="btn outline" data-close>Continue</button><button class="btn" id="finish">Finish & review</button></div>`);$('#finish').onclick=()=>{closeModal();finish();};}
function finish(){if(!test||test.done)return;clearInterval(tick);test.done=true;const qs=activeQuestions(),p=bankPapers.get(test.paperId),scorable=qs.filter(checkedQuestion),score=test.track==='PEA'?qs.reduce((n,q,i)=>n+(checkedQuestion(q)&&test.answers[i]===q.correctIndex?1:0),0):null;
 history.push({track:test.track,paperId:p.id,year:p.year,kind:p.kind,date:new Date().toISOString(),score,total:qs.length,scorableTotal:test.track==='PEA'?scorable.length:0,answered:qs.filter((_,i)=>answered(i)).length,durationSeconds:Math.round((Date.now()-test.startedAt)/1000),details:qs.map((q,i)=>({id:q.id,topic:q.topic,status:test.track==='PEA'?(!checkedQuestion(q)?'ungraded':test.answers[i]===undefined?'skipped':test.answers[i]===q.correctIndex?'correct':'incorrect'):(answered(i)?'practiced':'unreviewed'),hintUsed:Boolean(test.helpUsed[i]?.hint),solutionViewed:Boolean(test.helpUsed[i]?.solution)}))});save('econprep-history',history);
 $('#content').innerHTML=`${heading(test.track==='PEA'?`${score}/${scorable.length} correct`:'Practice complete',p.title)}${test.track==='PEA'?`<div class="notice">Unweighted practice score. ${qs.length-scorable.length} source-issue items excluded from scoring.</div>`:''}<section class="result">${qs.map((q,i)=>`<div class="result-item"><span class="badge-result">Question ${safe(questionNumber(q))} · ${safe(q.topic)}</span><div class="question-stem">${questionBody(q)}</div>${test.track==='PEA'?`<p>Your answer: ${test.answers[i]===undefined?'Skipped':rich(q.options[test.answers[i]])}</p>`:''}<details><summary>Hint</summary><div class="solution hint-panel">${rich(q.hint)}</div></details><details><summary>Answer & worked solution</summary>${worked(q)}</details><button class="text-button" data-save-question="${q.id}">${bookmarks.includes(q.id)?'✓ Saved':'♧ Save question'}</button></div>`).join('')}<div class="result-actions"><button class="btn" data-go="practice">Choose another paper ↗</button><button class="btn outline" data-go="analytics">Analytics</button></div></section>`;mathNow();window.scrollTo(0,0);}
function openPaperAnswers(id){const p=bankPapers.get(id);if(!p?.itemCount)return;closeModal();$('#crumb').textContent=`${p.year} ${p.paper} · Solutions`;$('#content').innerHTML=`${heading(p.title,'Answers and independently worked solutions')}<div class="notice">${p.checkedCount} checked items${p.reviewCount?` · ${p.reviewCount} source issues flagged`:''}. Check the source notes where a statement is ambiguous.</div><section class="result">${p.questionIds.map(id=>{const q=bankQuestions.get(id);return `<article class="result-item"><span class="badge-result">Question ${safe(questionNumber(q))} · ${safe(q.topic)}</span><div class="question-stem">${questionBody(q)}</div>${q.options&&q.paper!=='PEB'&&!q.imageOptions?`<ol type="A" class="review-options">${q.options.map(o=>`<li>${rich(o)}</li>`).join('')}</ol>`:''}<details><summary>Hint</summary><div class="solution hint-panel">${rich(q.hint)}</div></details><details><summary>Answer & worked solution</summary>${worked(q)}</details><button class="text-button" data-save-question="${q.id}">${bookmarks.includes(q.id)?'✓ Saved':'♧ Save question'}</button></article>`;}).join('')}</section>`;mathNow();window.scrollTo(0,0);}
function lookupSaved(id){if(bankQuestions.has(id))return bankQuestions.get(id);const m=/^(PEA|PEB)-(\d+)$/.exec(id);const q=m&&questions[m[1]]?.[Number(m[2])];return q?{...q,id,stem:q.q,answer:q.options?q.options[q.answer]:'See solution',number:String(Number(m[2])+1),status:'verified',kind:'warmup'}:null;}
function bookmarksPage(){const saved=bookmarks.map(lookupSaved).filter(Boolean);return `${heading('Bookmarks')}${saved.length?saved.map(q=>`<article class="result"><span class="pill">${q.year||'Warmup'} · ${safe(q.topic)}</span><div class="question-stem">${questionBody(q)}</div><details><summary>Answer & worked solution</summary>${worked(q)}</details><button class="text-button" data-remove="${q.id}">Remove bookmark</button></article>`).join(''):'<div class="empty"><h3>No saved questions.</h3><button class="btn" data-go="papers">Choose a paper ↗</button></div>'}`;}
const navigateBeforeBank=navigate;
navigate=function(next){navigateBeforeBank(next);mathNow();};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.bankStart)startPaper(b.dataset.bankStart);if(b.dataset.bankPreview){const p=bankPapers.get(b.dataset.bankPreview);paperPreview(p.year,p.paper,p.id);}if(b.dataset.bankReview)openPaperAnswers(b.dataset.bankReview);});
navigate('overview');
